<?php
// فتح وسم PHP لبدء كتابة الكود

// platform_check.php @generated by Composer
// تعليق توضيحي:
// - platform_check.php : اسم الملف
// - @generated by Composer : مُولَّد تلقائياً بواسطة Composer
// - الفائدة: فحص توافق المنصة (إصدار PHP) قبل تحميل أي شيء

$issues = array();
// مصفوفة فارغة لتخزين المشاكل المُكتشَفة
// - الفائدة: نجمع كل المشاكل ثم نعرضها معاً (بدلاً من واحدة واحدة)

if (!(PHP_VERSION_ID >= 50500)) {
// فحص إصدار PHP:
// - PHP_VERSION_ID : ثابت مُدمج في PHP (مثل 80100 لـ 8.1.0)
// - 50500 = 5.05.00 = PHP 5.5.0
// - !(شرط) : إذا لم يكن الإصدار >= 5.5.0
// - الفائدة: Composer يفحص أن PHP يلبي الحد الأدنى

    $issues[] = 'Your Composer dependencies require a PHP version ">= 5.5.0". You are running ' . PHP_VERSION . '.';
    // إضافة رسالة خطأ للمصفوفة:
    // - PHP_VERSION : الإصدار الفعلي (مثل '8.1.0')
    // - الفائدة: توضيح سبب المشكلة للمستخدم
}

if ($issues) {
// فحص: إذا كانت هناك مشاكل مُكتشَفة

    if (!headers_sent()) {
    // فحص: هل تم إرسال headers بعد؟
    // - headers_sent() : ترجع true إذا أُرسِلت الترويسات
    // - ! : لم تُرسَل بعد → يمكننا إرسال ترويسات

        header('HTTP/1.1 500 Internal Server Error');
        // إرسال ترويسة HTTP 500 (خطأ في السيرفر)
        // - الفائدة: يخبر المتصفح ومحركات البحث أن هناك خطأ
        // - ملاحظة: الحالة الافتراضية 200 (نجاح) → يجب تغييرها يدوياً
    }

    if (!ini_get('display_errors')) {
    // فحص: هل عرض الأخطاء مُعطَّل في php.ini؟
    // - ini_get('display_errors') : ترجع '1' إذا مفعّل، '' إذا معطَّل
    // - ! : معطَّل → سنعالج الإخراج يدوياً
    // - الفائدة: في الإنتاج، display_errors عادةً معطَّل

        if (PHP_SAPI === 'cli' || PHP_SAPI === 'phpdbg') {
        // فحص: هل نحن في سطر الأوامر (CLI)؟
        // - PHP_SAPI : واجهة تشغيل PHP
        // - 'cli' : Command Line Interface
        // - 'phpdbg' : أدوات التصحيح

            fwrite(STDERR, 'Composer detected issues in your platform:' . PHP_EOL.PHP_EOL . implode(PHP_EOL, $issues) . PHP_EOL.PHP_EOL);
            // كتابة رسالة إلى STDERR (الخطأ القياسي):
            // - STDERR : قناة الأخطاء في CLI
            // - PHP_EOL : نهاية السطر (\n في Linux، \r\n في Windows)
            // - implode(PHP_EOL, $issues) : دمج كل المشاكل بسطر جديد بينها
            // - الفائدة: إظهار الخطأ في الطرفية للمطورين
        } elseif (!headers_sent()) {
        // وإلا: إذا لم نكن في CLI (نحن في المتصفح)

            echo 'Composer detected issues in your platform:' . PHP_EOL.PHP_EOL . str_replace('You are running '.PHP_VERSION.'.', '', implode(PHP_EOL, $issues)) . PHP_EOL.PHP_EOL;
            // طباعة رسالة للمتصفح:
            // - str_replace : إزالة الجزء "You are running X.X.X" (لأسباب أمنية)
            //   * السبب: في الإنتاج لا نريد كشف إصدار PHP للمهاجمين
            // - الفائدة: رسالة واضحة بدون كشف معلومات حساسة
        }
    }

    throw new \RuntimeException(
    // إطلاق استثناء (Exception):
    // - يُوقف التنفيذ فوراً
    // - يمكن التقاطه بـ try/catch

        'Composer detected issues in your platform: ' . implode(' ', $issues)
        // نص الاستثناء:
        // - implode(' ', $issues) : دمج كل المشاكل بمسافة
        // - الفائدة: تمرير المشاكل للطبقة الأعلى
    );
}
// إغلاق الشرط الرئيسي